// Anfrage lesen (Stefan 18.10.2026): Herkunft und Sitzung wie ALLY 8/ALLY 10, Formularfelder der Seiten Talents › Berichte und › Zahlen ohne Verbindung.
// art: berichte (POST /talents-berichte), zahlen (POST /talents-zahlen, auch mit Datei), datei (GET /talents-datei?id=).
// Geheimnisse gibt es hier nicht; die Sitzung (Cookie) geht nur an die Datenbank. Dieser Ablauf speichert keine Ausführungsdaten.
const item = $input.first();
const h = item.json.headers || {}, b = item.json.body || {}, q = item.json.query || {};
const url = String(item.json.webhookUrl || '');
const ART = /\/talents-datei(\?|$)/.test(url) ? 'datei' : /\/talents-zahlen(\?|$)/.test(url) ? 'zahlen' : 'berichte';
const HOST = (x => /^[a-z0-9.-]{1,253}$/.test(x) ? 'https://' + x : '')(String(h.host || '').trim().toLowerCase());
const herkunft = String(h.origin || ''), verweis = String(h.referer || '');
const SEITE_PFAD = HOST + '/webhook/web';
const vonSeite = verweis.startsWith(SEITE_PFAD) && (verweis.length === SEITE_PFAD.length || '/?#'.includes(verweis[SEITE_PFAD.length]));
const herkunftOk = ART === 'datei' || (HOST !== '' && (herkunft === HOST || ((herkunft === '' || herkunft === 'null') && vonSeite)));
const kekse = String(h.cookie || '').split(';').map(x => x.trim());
const roh = (kekse.find(x => x.startsWith('ally_sitzung=')) || '').slice('ally_sitzung='.length);
const token = /^[0-9a-f]{64}$/.test(roh) ? roh : '';
const s = v => String(Array.isArray(v) ? (v[0] ?? '') : (v ?? '')).replace(/[\x00-\x1f\x7f]/g, ' ').trim().slice(0, 300);
const liste = (...k) => { const out = []; for (const n of k) { const v = b[n]; (Array.isArray(v) ? v : (v === undefined ? [] : [v])).forEach(x => { const t = s(x); if (t) out.push(t); }); } return out.slice(0, 20); };
// Herunterladen (Stefan 18.10.2026): ?id=<bericht_id> (Bericht, Migration 47) oder ?datei=<datei_id> (Datei der Talents-Ablage, Migration 49, aktion "ablage").
// zurueck: die eigene Seite aus dem Verweis (nur Pfad und Adressparameter) für den Rücksprung bei Fehlern, sonst leer.
if (ART === 'datei') {
  const ablage = q.datei !== undefined;
  const id = ablage ? (/^[0-9]{1,15}$/.test(String(q.datei)) ? String(q.datei) : '') : (/^[0-9]{1,12}$/.test(String(q.id || '')) ? String(q.id) : '');
  const rest = vonSeite ? verweis.slice(HOST.length).split('#')[0] : '';
  const zurueck = /^\/webhook\/web(\?[A-Za-z0-9=&_%.-]{0,300})?$/.test(rest) ? rest : '';
  return [{ json: { art: ART, token, aktion: ablage ? 'ablage' : 'datei', id, zurueck, daten: '{}' } }];
}
const AKTIONEN = ART === 'berichte' ? ['erstellen', 'vorlage_speichern', 'vorlage_loeschen', 'vorlage_erstellen'] : ['hochladen', 'bestaetigen', 'verwerfen', 'wert_neu', 'wert_loeschen'];
let aktion = s(b.aktion);
if (!AKTIONEN.includes(aktion)) aktion = 'unbekannt';
if (!herkunftOk) aktion = 'ungueltig';
let daten = {};
if (ART === 'berichte') {
  daten = { art: s(b.art), talents: liste('talents', 'talents[]', 'talent'), kanal: s(b.kanal), zeitraum: s(b.zeitraum), von: s(b.von), bis: s(b.bis), monat: s(b.monat),
    bausteine: liste('bausteine', 'bausteine[]'), mit_agentur: s(b.mit_agentur) === 'nein' ? 'nein' : 'ja', kampagne_id: s(b.kampagne_id), titel: s(b.titel).slice(0, 80),
    vorlage_id: s(b.vorlage_id), vorlage_name: s(b.vorlage_name).slice(0, 81), plan: s(b.plan) };
  // "Als Vorlage speichern" ist ein zweiter Knopf im selben Formular (name="aktion" value="vorlage_speichern")
} else {
  for (const [k, v] of Object.entries(b)) if (/^(n[0-9]{1,2}_(ja|wert|von|bis)|vorschlag_id|wert_id|talent_id|plattform|kennzahl|wert|von|bis|konto)$/.test(k)) daten[k] = s(v);
  if (aktion === 'hochladen') {
    const bin = item.binary || {};
    const k = Object.keys(bin).find(x => x === 'datei') || Object.keys(bin).find(x => x.startsWith('datei'));
    if (k) {
      const buf = await this.helpers.getBinaryDataBuffer(0, k);
      const name = s(bin[k].fileName).slice(0, 120);
      let typ = String(bin[k].mimeType || '').toLowerCase().split(';')[0].trim();
      const ende = (name.split('.').pop() || '').toLowerCase();
      if (typ === 'image/jpg') typ = 'image/jpeg';
      if (!typ || typ === 'application/octet-stream' || typ === 'text/plain') typ = { csv: 'text/csv', txt: 'text/plain', json: 'application/json', pdf: 'application/pdf', png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', webp: 'image/webp' }[ende] || typ;
      Object.assign(daten, { datei_name: name, datei_typ: typ, datei_groesse: String(buf.length), binaer: k });
    } else Object.assign(daten, { datei_groesse: '0' });
  }
}
return [{ json: { art: ART, token, aktion, daten: JSON.stringify(daten), binaer: daten.binaer || '' } }];

// Dateiauftrag (Stefan 18.10.2026): erlaubte Datei aus dem Speicherort holen (SPEICHER 1, Bereich ally);
// Datei der Talents-Ablage über TALENTS Ablage (aktion holen, datei_id), die den Dienst (Ally, Google Drive, OneDrive, SharePoint, Dropbox) selbst kennt
const r = $('Datei prüfen').first().json.r || {};
if ($('Anfrage lesen').first().json.aktion === 'ablage') return [{ json: { aktion: 'holen', datei_id: Number(r.datei_id) } }];
return [{ json: { aktion: 'holen', bereich: 'ally', pfad: r.pfad } }];

// Antwort bauen (Stefan 18.10.2026): 303 zurück zur Seite (Meldung steht in der Sitzung), Sitzung wie ALLY 8/ALLY 10 behandeln
const SEITE = '/webhook/web';
const F = $('Anfrage lesen').first().json;
const r = $input.first().json.r || {};
const keks = (wert, alter) => 'ally_sitzung=' + wert + '; Path=' + SEITE + '; Max-Age=' + alter + '; HttpOnly; Secure; SameSite=None';
let ziel, cookie = '';
if (F.aktion === 'ungueltig') ziel = SEITE + '?m=ungueltig';
else if (r.angemeldet === false) { ziel = SEITE + '?m=abgelaufen'; cookie = keks('', 0); }
else {
  const z = String(r.ziel || '');
  ziel = /^\/webhook\/web(\?[A-Za-z0-9=&_%.#-]*)?(#[A-Za-z0-9_-]*)?$/.test(z) ? z : SEITE + '?ansicht=talents';
  if (F.token) cookie = keks(F.token, 2592000);
}
return [{ json: { ziel, set_cookie: cookie, weiter: r.ok === true ? (r.weiter || '') : '' } }];

// Datei weitergeben (Stefan 18.10.2026): Vorschlag (aus der Datenbank) und hochgeladene Datei an "TALENTS Zahlen auslesen"
const F = $('Anfrage lesen').first().json;
const r = $('Aktion ausführen').first().json.r || {};
const w = $('Zahlen ohne Verbindung').first();
const bin = w.binary || {};
const k = F.binaer && bin[F.binaer] ? F.binaer : null;
return [{ json: { quelle: 'hochladen', nutzer: r.nutzer, vorschlag: r.vorschlag }, binary: k ? { datei: bin[k] } : {} }];

// Download nicht möglich (Stefan 18.10.2026): zurück zu Talents › Berichte (Meldung steht in der Sitzung);
// Datei der Talents-Ablage: zurück auf die Seite, von der der Link kam (Abschnitt Dateien), sonst zu den Talents
const SEITE = '/webhook/web';
const F = $('Anfrage lesen').first().json;
const r = $('Datei prüfen').first().json.r || {};
if (r.angemeldet === false) return [{ json: { ziel: SEITE + '?m=abgelaufen', set_cookie: 'ally_sitzung=; Path=' + SEITE + '; Max-Age=0; HttpOnly; Secure; SameSite=None' } }];
if (F.aktion === 'ablage') return [{ json: { ziel: F.zurueck ? F.zurueck + '#dateien' : SEITE + '?ansicht=talents', set_cookie: '' } }];
return [{ json: { ziel: SEITE + '?ansicht=talents&b=berichte#liste', set_cookie: '' } }];
